mapper.sql:
WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{cmpnyCd} AND N.NODE_CD = #{nodeCd}
AND N.SITE_CD = #{siteCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )

WHERE U.CMPNY_CD = #{cmpnyCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL AND U.ACCOUNT_STATUS IN ('01', '04') /* B-1(2026-08-22): 일용직 명시 제외 — 일용직은 비활성(USE_YN='N'/계정상태 05) 유지 설계라 현재도 비노출이지만 데이터 상태 의존을 제거한다(개발 DB에 활성 DAILY 통합계정 실존 확인). EMPLOYMENT_TYPE 이 NULL 인 활성 직원이 걸러지지 않도록 IS NULL 허용 형태를 유지할 것. */ AND (U.EMPLOYMENT_TYPE IS NULL OR U.EMPLOYMENT_TYPE != 'DAILY')
AND U.SITE_CD = #{siteCd}
AND EXISTS ( SELECT 1 FROM node_tree NT WHERE NT.CMPNY_CD = U.CMPNY_CD AND NT.SITE_CD = U.SITE_CD AND NT.NODE_CD = U.NODE_CD )
AND U.NODE_CD = #{nodeCd}
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')

mapper.select:
/* LeaveDashboardMapper.selectDashboardList */
SELECT U.USER_CD AS userCd , U.USER_NM AS userNm , N.NODE_NM AS deptNm , U.HIRE_DATE AS hireDate , U.EMPLOYMENT_TYPE AS employmentType , IFNULL(( SELECT SUM(C.CREDIT_MONTHS) FROM TB_USER_SERVICE_CREDIT C WHERE C.CMPNY_CD = U.CMPNY_CD AND C.USER_CD = U.USER_CD AND C.USE_YN = 'Y' AND C.LEAVE_CALC_YN = 'Y' ), 0) AS creditMonths , IFNULL(( SELECT SUM(G.GRANT_DAYS) FROM TB_USER_LEAVE_GRANT G WHERE G.CMPNY_CD = U.CMPNY_CD AND G.USER_CD = U.USER_CD AND G.DEL_YN = 'N' AND G.STATUS = 'ACTIVE' AND G.GRANT_TYPE LIKE 'STATUTORY\_%' ), 0) AS legalGranted , IFNULL(( SELECT SUM(G.USED_DAYS) FROM TB_USER_LEAVE_GRANT G WHERE G.CMPNY_CD = U.CMPNY_CD AND G.USER_CD = U.USER_CD AND G.DEL_YN = 'N' AND G.STATUS = 'ACTIVE' AND G.GRANT_TYPE LIKE 'STATUTORY\_%' ), 0) AS legalUsed
, IFNULL(( SELECT SUM(LU.LEAVE_DAYS) FROM TB_USER_LEAVE_USE LU JOIN TB_USER_LEAVE_GRANT G ON G.CMPNY_CD = LU.CMPNY_CD AND G.GRANT_ID = LU.GRANT_ID AND G.DEL_YN = 'N' AND G.STATUS = 'ACTIVE' AND G.GRANT_TYPE LIKE 'STATUTORY\_%' WHERE LU.CMPNY_CD = U.CMPNY_CD AND LU.USER_CD = U.USER_CD AND LU.LEAVE_STATUS = 'CONFIRMED' AND LU.DEL_YN = 'N' AND LU.START_DATE > DATE_FORMAT(NOW(), '%Y%m%d') ), 0) AS legalScheduled , IFNULL(( SELECT SUM(G.GRANT_DAYS) FROM TB_USER_LEAVE_GRANT G WHERE G.CMPNY_CD = U.CMPNY_CD AND G.USER_CD = U.USER_CD AND G.DEL_YN = 'N' AND G.STATUS = 'ACTIVE' AND G.GRANT_TYPE LIKE 'MANUAL\_%' ), 0) AS nonLegalGranted , IFNULL(( SELECT SUM(G.USED_DAYS) FROM TB_USER_LEAVE_GRANT G WHERE G.CMPNY_CD = U.CMPNY_CD AND G.USER_CD = U.USER_CD AND G.DEL_YN = 'N' AND G.STATUS = 'ACTIVE' AND G.GRANT_TYPE LIKE 'MANUAL\_%' ), 0) AS nonLegalUsed
, IFNULL(( SELECT SUM(LU.LEAVE_DAYS) FROM TB_USER_LEAVE_USE LU JOIN TB_USER_LEAVE_GRANT G ON G.CMPNY_CD = LU.CMPNY_CD AND G.GRANT_ID = LU.GRANT_ID AND G.DEL_YN = 'N' AND G.STATUS = 'ACTIVE' AND G.GRANT_TYPE LIKE 'MANUAL\_%' WHERE LU.CMPNY_CD = U.CMPNY_CD AND LU.USER_CD = U.USER_CD AND LU.LEAVE_STATUS = 'CONFIRMED' AND LU.DEL_YN = 'N' AND LU.START_DATE > DATE_FORMAT(NOW(), '%Y%m%d') ), 0) AS nonLegalScheduled
, IFNULL(( SELECT SUM(G.USED_DAYS) FROM TB_USER_LEAVE_GRANT G WHERE G.CMPNY_CD = U.CMPNY_CD AND G.USER_CD = U.USER_CD AND G.GRANT_REASON LIKE '[가불]%' AND G.STATUS != 'CANCELED' AND G.DEL_YN = 'N' AND G.AVAIL_FROM_DATE > DATE_FORMAT(NOW(), '%Y%m%d') ), 0) AS borrowedDays FROM TB_USER U LEFT JOIN TB_SITE_NODE N ON N.CMPNY_CD = U.CMPNY_CD AND N.SITE_CD = U.SITE_CD AND N.NODE_CD = U.NODE_CD
ORDER BY U.USER_NM ASC, U.USER_CD ASC LIMIT #{limit} OFFSET #{offset}

/* LeaveDashboardMapper.countDashboardList */



SELECT COUNT(*)
  FROM TB_USER U

/* LeaveDashboardMapper.countManualGrantType */
SELECT COUNT(*)
  FROM TB_LEAVE_TYPE_MGMT T
 WHERE T.CMPNY_CD = #{cmpnyCd}
   AND T.LEAVE_CD = #{leaveCd}
   AND T.LEAVE_TYPE = '02'
   AND T.GRANT_TYPE = '02'
   AND T.USE_YN = 'Y'

/* LeaveDashboardMapper.countActiveUser */
SELECT COUNT(*)
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.USER_CD  = #{userCd}
   AND U.USE_YN = 'Y'
   AND U.WITHDRAWAL_DATE IS NULL
   AND U.ACCOUNT_STATUS IN ('01', '04')

/* LeaveDashboardMapper.selectNextGrantId */
SELECT CONCAT('G', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'LEAVE_GRANT_ID'))
  FROM DUAL

mapper.insert:
/* LeaveDashboardMapper.insertManualGrant */
INSERT INTO TB_USER_LEAVE_GRANT (
      GRANT_ID
    , CMPNY_CD
    , USER_CD
    , LEAVE_CD
    , GRANT_TYPE
    , GRANT_DAYS
    , USED_DAYS
    , GRANT_REASON
    , GRANT_BY_TYPE
    , POLICY_SEQ
    , GRANT_DATE
    , AVAIL_FROM_DATE
    , AVAIL_TO_DATE
    , IDEMPOTENCY_KEY
    , STATUS
    , EXPIRE_YN
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{grantId}
    , #{cmpnyCd}
    , #{userCd}
    , #{leaveCd}
    , #{grantType}
    , #{grantDays}
    , #{usedDays}
    , #{grantReason}
    , #{grantByType}
    , #{policySeq}
    , #{grantDate}
    , #{availFromDate}
    , #{availToDate}
    , #{idempotencyKey}
    , #{status}
    , 'N'
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.update:
/* LeaveDashboardMapper.recallGrant */
UPDATE TB_USER_LEAVE_GRANT
   SET STATUS        = 'CANCELED'
     , CANCEL_REASON = #{reason}
     , CANCEL_DATE   = NOW()
     , CANCEL_BY     = #{operatorUserCd}
     , UPDATE_NO     = #{operatorUserCd}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND GRANT_ID = #{grantId}
   AND STATUS   = 'ACTIVE'
   AND DEL_YN   = 'N'

