/* LeaveDashboardMapper.selectNextNotiId */
SELECT CONCAT('N', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'NOTI_OUTBOX_ID'))
  FROM DUAL

