/* LeaveDashboardMapper.insertNotiOutbox */
INSERT INTO TB_NOTI_OUTBOX (
      NOTI_ID
    , CMPNY_CD
    , SITE_CD
    , TARGET_USER_CD
    , NOTI_TYPE
    , CHANNEL
    , TITLE
    , BODY
    , DATA_PAYLOAD
    , SEND_STATUS
    , RETRY_CNT
    , DEDUP_KEY
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{notiId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{targetUserCd}
    , #{notiType}
    , #{channel}
    , #{title}
    , #{body}
    , #{dataPayload}
    , #{sendStatus}
    , 0
    , #{dedupKey}
    , 'N'
    , #{insertNo}
    , NOW()
)

