/* LeaveDashboardMapper.reactivateCanceledGrant */
UPDATE TB_USER_LEAVE_GRANT
   SET STATUS          = 'ACTIVE'
     , EXPIRE_YN       = 'N'
     , EXPIRE_DATE     = NULL
     , GRANT_DATE      = #{grantDate}
     , AVAIL_FROM_DATE = #{availFromDate}
     , AVAIL_TO_DATE   = #{availToDate}
     , GRANT_DAYS      = #{grantDays}
     , POLICY_SEQ      = #{policySeq}
     , GRANT_REASON    = #{grantReason}
     , GRANT_BY_TYPE   = #{grantByType}
     , UPDATE_NO       = #{insertNo}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD        = #{cmpnyCd}
   AND IDEMPOTENCY_KEY = #{idempotencyKey}
   AND STATUS          = 'CANCELED'
   AND DEL_YN          = 'N'

mapper.select:
/* LeaveDashboardMapper.selectCanceledGrantIdByKey */
SELECT G.GRANT_ID
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD        = #{cmpnyCd}
   AND G.IDEMPOTENCY_KEY = #{idempotencyKey}
   AND G.STATUS          = 'CANCELED'
   AND G.DEL_YN          = 'N'
 LIMIT 1

/* LeaveDashboardMapper.selectUserHireDate */
SELECT U.HIRE_DATE
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.USER_CD  = #{userCd}
   AND U.USE_YN = 'Y'
   AND U.WITHDRAWAL_DATE IS NULL
   AND U.ACCOUNT_STATUS IN ('01', '04')

/* LeaveDashboardMapper.countByIdempotencyKey */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD        = #{cmpnyCd}
   AND G.IDEMPOTENCY_KEY = #{idempotencyKey}

/* LeaveDashboardMapper.countLiveByIdempotencyKey */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD        = #{cmpnyCd}
   AND G.IDEMPOTENCY_KEY = #{idempotencyKey}
   AND G.STATUS != 'CANCELED'
   AND G.DEL_YN  = 'N'

/* LeaveDashboardMapper.countActiveByIdempotencyKey */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD        = #{cmpnyCd}
   AND G.IDEMPOTENCY_KEY = #{idempotencyKey}
   AND G.STATUS          = 'ACTIVE'
   AND G.DEL_YN          = 'N'

/* LeaveDashboardMapper.countLeaveTypeExists */
SELECT COUNT(*)
  FROM TB_LEAVE_TYPE_MGMT T
 WHERE T.CMPNY_CD = #{cmpnyCd}
   AND T.LEAVE_CD = #{leaveCd}
   AND T.USE_YN = 'Y'

/* LeaveDashboardMapper.selectCreditMonths */
SELECT IFNULL(SUM(C.CREDIT_MONTHS), 0)
  FROM TB_USER_SERVICE_CREDIT C
 WHERE C.CMPNY_CD = #{cmpnyCd}
   AND C.USER_CD  = #{userCd}
   AND C.USE_YN   = 'Y'
   AND C.LEAVE_CALC_YN = 'Y'

/* LeaveDashboardMapper.selectExtraLeaveDaysSum */
SELECT IFNULL(SUM(C.EXTRA_LEAVE_DAYS), 0)
  FROM TB_USER_SERVICE_CREDIT C
 WHERE C.CMPNY_CD = #{cmpnyCd}
   AND C.USER_CD  = #{userCd}
   AND C.USE_YN   = 'Y'
   AND C.LEAVE_CALC_YN = 'N'

/* LeaveDashboardMapper.selectStatutoryGrantAccrual */
SELECT IFNULL(SUM(
            G.USED_DAYS
          + CASE WHEN G.AVAIL_TO_DATE  >=  #{today}
                 THEN G.GRANT_DAYS - G.USED_DAYS
                 ELSE 0
            END
       ), 0)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD   = #{cmpnyCd}
   AND G.USER_CD    = #{userCd}
   AND G.GRANT_TYPE LIKE 'STATUTORY\_%'
   AND G.STATUS    != 'CANCELED'
   AND G.DEL_YN     = 'N'

/* LeaveDashboardMapper.selectStatutoryAnnualTenureAccrual */
SELECT IFNULL(SUM(
            G.USED_DAYS
          + CASE WHEN G.AVAIL_TO_DATE  >=  #{today}
                 THEN G.GRANT_DAYS - G.USED_DAYS
                 ELSE 0
            END
       ), 0)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD   = #{cmpnyCd}
   AND G.USER_CD    = #{userCd}
   AND G.GRANT_TYPE IN ('STATUTORY_ANNUAL', 'STATUTORY_TENURE_BONUS')
   AND G.STATUS    != 'CANCELED'
   AND G.DEL_YN     = 'N'

/* LeaveDashboardMapper.selectBorrowedDaysTotal */
SELECT IFNULL(SUM(G.USED_DAYS), 0)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD       = #{cmpnyCd}
   AND G.USER_CD        = #{userCd}
   AND G.GRANT_REASON   LIKE '[가불]%'
   AND G.GRANT_TYPE     LIKE CONCAT(REPLACE(#{grantTypePrefix}, '_', '\_'), '%')
   AND G.STATUS        != 'CANCELED'
   AND G.DEL_YN         = 'N'
   AND G.AVAIL_FROM_DATE  >  #{today}

/* LeaveDashboardMapper.selectBorrowGrantIdsForCancel */
SELECT DISTINCT G.GRANT_ID
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD     = #{cmpnyCd}
   AND G.GRANT_REASON LIKE '[가불]%'
   AND G.STATUS       = 'ACTIVE'
   AND G.DEL_YN       = 'N'
   AND G.USED_DAYS    = 0
   AND G.GRANT_ID IN (
         SELECT U.GRANT_ID
           FROM TB_USER_LEAVE_USE U
          WHERE U.CMPNY_CD = #{cmpnyCd}
            AND U.REQ_ID   = #{reqId}
            AND U.GRANT_ID IS NOT NULL
       )

mapper.update:
/* LeaveDashboardMapper.cancelBorrowGrant */
UPDATE TB_USER_LEAVE_GRANT
   SET STATUS        = 'CANCELED'
     , CANCEL_REASON = '[가불] 신청 반려/취소 자동 회수'
     , CANCEL_DATE   = NOW()
     , CANCEL_BY     = #{operatorUserCd}
     , UPDATE_NO     = #{operatorUserCd}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD     = #{cmpnyCd}
   AND GRANT_ID     = #{grantId}
   AND STATUS       = 'ACTIVE'
   AND DEL_YN       = 'N'
   AND USED_DAYS    = 0
   AND GRANT_REASON LIKE '[가불]%'

mapper.select:
/* LeaveDashboardMapper.selectHourlyUsedMinutes */
SELECT IFNULL(SUM(U.LEAVE_MINUTES), 0)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD      = #{cmpnyCd}
   AND U.USER_CD       = #{userCd}
   AND U.USE_UNIT_TYPE IN ('02', '03', '04')
   AND U.LEAVE_STATUS  = 'CONFIRMED'
   AND U.DEL_YN        = 'N'

/* LeaveDashboardMapper.selectShortfallCandidateList */
SELECT U.USER_CD AS userCd , U.USER_NM AS userNm , U.HIRE_DATE AS hireDate FROM TB_USER U
AND U.HIRE_DATE IS NOT NULL ORDER BY U.USER_NM ASC, U.USER_CD ASC LIMIT #{limit} OFFSET #{offset}

/* LeaveDashboardMapper.countShortfallCandidateList */
SELECT COUNT(*) FROM TB_USER U
AND U.HIRE_DATE IS NOT NULL

/* LeaveDashboardMapper.selectCoverGrantTotal */
SELECT IFNULL(SUM(G.GRANT_DAYS), 0)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD        = #{cmpnyCd}
   AND G.USER_CD         = #{userCd}
   AND G.GRANT_BY_TYPE   = '02'
   AND G.IDEMPOTENCY_KEY LIKE '%\_COVER'
   AND G.STATUS         != 'CANCELED'
   AND G.DEL_YN          = 'N'

/* LeaveDashboardMapper.selectStatutoryGrantedLiveTotal */
SELECT IFNULL(SUM(G.GRANT_DAYS), 0)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD   = #{cmpnyCd}
   AND G.USER_CD    = #{userCd}
   AND G.GRANT_TYPE LIKE 'STATUTORY\_%'
   AND G.STATUS    != 'CANCELED'
   AND G.DEL_YN     = 'N'
